fun track_flash_loan_usage_test() {
    let mut scenario = ts::begin(ADMIN);
    random::create_for_testing(scenario.ctx());

    let mut referral = new(
        500,  // referrer_discount_bps: 5%
        400,  // referee_discount_bps: 4%
        10_000, // referrer_deposit_usd_threshold: $10000
        scenario.ctx()
    );

    referral.set_accumulated_deposit_usd_for( USER1, 10_001);

    scenario.next_tx(USER1);
    let referral_code = {
        let random = scenario.take_shared<Random>();
        referral.generate_referral_code( &random, scenario.ctx());

        // verify code was generated
        assert!(referral.referrer_code.contains(USER1), 0);
        let code = *referral.referrer_code.borrow(USER1);
        assert!(code.length() == 6, 1);
        ts::return_shared(random);
        code
    };

    scenario.next_tx( USER2);
    {
        let mut fee = coin::mint_for_testing<USDC>(1000, scenario.ctx());
        fee = referral.track_flash_loan_usage<USDC>(fee, referral_code, USER2, scenario.ctx());

        assert!(referral.user_rebates_records.contains(USER1), 1);
        assert!(referral.user_rebates_records.contains(USER2), 1);

        let user1_rebates = referral.user_rebates_records.borrow(USER1);
        let user2_rebates = referral.user_rebates_records.borrow(USER2);
        assert!(user1_rebates.contains(&type_name::with_defining_ids<USDC>()), 2);
        assert!(user2_rebates.contains(&type_name::with_defining_ids<USDC>()), 2);

        let user1_rebates_amount = *user1_rebates.get(&type_name::with_defining_ids<USDC>());
        let user2_rebates_amount = *user2_rebates.get(&type_name::with_defining_ids<USDC>());

        assert!(user1_rebates_amount == 1000 * 9_600 * 500 / 10_000 / 10_000, 3);
        assert!(user2_rebates_amount == 1000 * 400 / 10_000, 3);

        std::unit_test::destroy(fee);
    };

    std::unit_test::destroy(referral);
    ts::end(scenario);
}

